const passEncrypt = pass => {
  const dkey = '$D1g1c@rd#Cl0ud#Sys7em#Encr1p7#P@ssw0rd$';
  var dontEncrypt = false;
  var showEncrypted = false;

  // const JsCrypto = require("jscrypto");
  const DES3 = require('nodejs3des');

  function decrypt(msg) {
    // dMsg = JsCrypto.DES3.decrypt(msg, dkey).toString(JsCrypto.Utf8)
    const dMsg = DES3.decrypt(dkey, msg);
    // console.log('decripted (' + msg + '):' + dMsg)
    return dMsg;
  }

  function encrypt(msg) {
    // eMsg = JsCrypto.DES3.encrypt(msg, dkey).toString(JsCrypto.Utf8)
    // eMsg = JsCrypto.DES3.encrypt(msg, dkey).toString()
    const eMsg = DES3.encrypt(dkey, msg);
    // console.log('encripted (' + msg + '):' + eMsg)
    return eMsg;
  }

  if (pass.startsWith('[[')) {
    const passCmds = pass.match(/\[\[(.*)\]\](.*)/);
    pass = passCmds[2];

    for (i = 0; i < passCmds[1].length; i++) {
      const cmd = passCmds[1][i];
      console.log(`Cmd: ${cmd}`);
      switch (cmd) {
        case 'x':
          dontEncrypt = true;
          break;

        case '?':
          showEncrypted = true;
          break;
      }
    }
  }

  let passEncrypted = dontEncrypt ? pass : encrypt(pass);

  if (showEncrypted) alert(`pass: ${passEncrypted}`);

  // console.log('pass: ' + pass)
  // console.log('passEncrypted: ' + passEncrypted)
  // // console.log('passDecrypted: ' + decrypt(passEncrypted))

  // console.log('admlocal@email.com: ' + decrypt('0VB6iBoHtoY='))
  // console.log('usvis@email.com: ' + decrypt('BHmkzcNXYe0='))
  // console.log('20283309178@email.com: ' + decrypt('4sav0GonhZg='))

  return passEncrypted;

  // export default passEncrypt;
};

export default passEncrypt;
