import React, { useState, useEffect, useRef } from 'react';
import { Text, View } from 'react-native';
import Animated, {
  Easing,
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  withRepeat,
  withDelay,
  withSequence,
} from 'react-native-reanimated';
import { LinearGradient } from 'expo-linear-gradient';

const ShinyEffect = props => {
  let range = useSharedValue(0);
  const gradientWidth = 75;

  const animatedStyles = useAnimatedStyle(() => ({
    transform: [
      { translateX: range.value - gradientWidth },
      { skewX: '20deg' },
    ],
    // transform: [{ translateX: -0 }, { skewX: '20deg' }],
  }));

  React.useEffect(() => {
    range.value = withRepeat(
      withSequence(
        withTiming(800, {
          easing: Easing.in(Easing.bezierFn(0.25, 0.1, 0.25, 1)),
          duration: props.time || 2000,
        }),
        withTiming(800, { duration: 1000 })
      ),
      0,
      false
    );
  }, []);

  return (
    <Animated.View
      style={[
        {
          height: '100%',
          position: 'absolute',
          bottom: 0,
          right: 0,
          left: 0,
          top: 0,
        },
        animatedStyles,
      ]}
    >
      <LinearGradient
        style={{
          width: gradientWidth,
          height: '100%',
          bottom: 0,
          right: 0,
          left: 0,
        }}
        useAngle={true}
        angle={45}
        angleCenter={{ x: 0.5, y: 0.5 }}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 0 }}
        colors={[
          '#ffffff00',
          '#ffffff20',
          '#ffffffB3',
          '#ffffff20',
          '#ffffff00',
        ]}
      />
    </Animated.View>
  );
};

export default ShinyEffect;
