import React from 'react';
import { Button, ScreenContainer, Touchable, withTheme } from '@draftbit/ui';
import { useIsFocused } from '@react-navigation/native';
import { Image, Text, View } from 'react-native';
import * as CustomCode from '../CustomCode';
import * as DcSSApi from '../apis/DcSSApi.js';
import * as GlobalVariables from '../config/GlobalVariableContext';
import Images from '../config/Images';
import getNotificationToken from '../global-functions/getNotificationToken';
import palettes from '../themes/palettes';
import * as Utils from '../utils';
import Breakpoints from '../utils/Breakpoints';
import * as StyleSheet from '../utils/StyleSheet';
import imageSource from '../utils/imageSource';
import useWindowDimensions from '../utils/useWindowDimensions';

const CompletaInicioSessionScreen = props => {
  const { theme, navigation } = props;
  const dimensions = useWindowDimensions();
  const Constants = GlobalVariables.useValues();
  const Variables = Constants;
  const setGlobalVariableValue = GlobalVariables.useSetValue();
  const showVars = () => {
    const platform = CustomCode.Platform.OS;
    console.log(`platform: ${platform}`);

    // const constants = CustomCode.ExpoConstants[CustomCode.Platform.OS];
    const constants = CustomCode.ExpoConstants;
    console.log(`constants: ${JSON.stringify(constants)}`);

    const isDevice = CustomCode.Platform.OS !== 'web' && constants.isDevice;
    console.log(`isDevice: ${isDevice}`);
  };
  const dcSSEmployeeTokenPATCH = DcSSApi.useEmployeeTokenPATCH();
  const isFocused = useIsFocused();
  React.useEffect(() => {
    const handler = async () => {
      try {
        if (!isFocused) {
          return;
        }
        const expoTokenG = await getNotificationToken(Variables);
        setGlobalVariableValue({
          key: 'ExpoNotifToken',
          value: expoTokenG,
        });
        const tokenData = expoTokenG?.data;
        (
          await dcSSEmployeeTokenPATCH.mutateAsync({
            emp_id: Constants['my_emp_id'],
            emp_token: tokenData,
          })
        )?.json;
        /* hidden 'Conditional Stop' action */
        navigation.navigate('Main', { screen: 'InicioScreen' });
      } catch (err) {
        console.error(err);
      }
    };
    handler();
  }, [isFocused]);

  return (
    <ScreenContainer
      scrollable={false}
      hasSafeArea={true}
      style={StyleSheet.applyWidth(
        {
          backgroundColor: theme.colors.background.brand,
          justifyContent: 'space-between',
        },
        dimensions.width
      )}
    >
      <Utils.CustomCodeErrorBoundary>
        <CustomCode.DigicardScreenHeader {...props} left={{}} />
      </Utils.CustomCodeErrorBoundary>
      <View
        style={StyleSheet.applyWidth(
          { alignItems: 'center', flex: 1, justifyContent: 'center' },
          dimensions.width
        )}
      >
        <Image
          resizeMode={'contain'}
          source={imageSource(Images['FlipFlop'])}
          style={StyleSheet.applyWidth(
            { height: 100, marginBottom: 16, overflow: 'hidden', width: 100 },
            dimensions.width
          )}
        />
        <Text
          accessible={true}
          selectable={false}
          ellipsizeMode={'tail'}
          style={StyleSheet.applyWidth(
            {
              alignSelf: 'center',
              color: theme.colors.text.strong,
              fontFamily: 'System',
              fontSize: 28,
              fontWeight: '700',
              marginBottom: 10,
              marginTop: 30,
              textAlign: 'center',
            },
            dimensions.width
          )}
          textBreakStrategy={'highQuality'}
        >
          {'Inicializando tus datos...'}
        </Text>

        <Text
          accessible={true}
          selectable={false}
          ellipsizeMode={'tail'}
          style={StyleSheet.applyWidth(
            {
              alignSelf: 'center',
              color: theme.colors.text.strong,
              fontSize: 16,
              lineHeight: 28,
              marginLeft: '3%',
              marginRight: '3%',
              textAlign: 'center',
            },
            dimensions.width
          )}
          textBreakStrategy={'highQuality'}
        >
          {'Un momento por favor...'}
        </Text>
      </View>
    </ScreenContainer>
  );
};

export default withTheme(CompletaInicioSessionScreen);
