const minBarText = 7; // Porcentual mínimo de una barra para mostrar su valor

const SegmentedProgressBar = ({
  labels,
  values,
  colors,
  height = 8,
  borderRadius,
  showSeparatorValue,
  showValueInside,
  colorValuesShown = [],
  position = null,
  positionColor = 'black',
  animated = null,
}) => {
  const sectionsPercentage = []; // Array de valores convertidos a porcentajes (suman 100)

  // console.log('values:', values);

  function inHours(dur) {
    return (
      Math.floor(dur.asHours()) + moment(dur.asMilliseconds()).format('[:]mm')
    );
  }

  function ifTime2minutes(v) {
    if (typeof v === 'number') return v;
    if (moment.isDuration(v)) return v;
    if (typeof v === 'string') {
      if (v.includes(':')) {
        if (v.includes('T')) v = v.split('T')[1];
        return moment.duration(v);
      }
      return Number(v);
    }
  }

  const ivalues = values.map((v, i) => {
    return ifTime2minutes(v);
  });

  ivalues.forEach((el, idx, arr) => {
    if (idx > 0 && moment.isDuration(el)) {
      let mod = false;
      while (el < arr[idx - 1]) {
        el.add(1, 'days');
        mod = true;
      }
      if (mod) {
        arr[idx] = el;
      }
    }
  });

  // console.log('values:', values.length, values);
  // console.log('ivalues:', ivalues.length, ivalues);
  // console.log('last ivalue:', ivalues[ivalues.length - 1]);
  // console.log('last ivalue:', ivalues.slice(-1)[0]);

  const finalValue = ivalues.slice(-1)[0]; // Ultimo valor
  let adjustedFinalValue = finalValue - ivalues[0]; // Dif total entre ultimo y primero
  if (moment.isDuration(finalValue)) {
    adjustedFinalValue = moment.duration(adjustedFinalValue);
  }
  // console.log('finalValue, adjustedFinalValue:', finalValue, adjustedFinalValue);

  const barValues = [];

  ivalues.forEach((v, i) => {
    if (i < ivalues.length - 1 && adjustedFinalValue !== 0) {
      let barValue = ivalues[i + 1] - v;

      if (moment.isDuration(v)) {
        barValue = moment.duration(barValue);
      }
      // console.log('barValue:', barValue);

      const perc = (100 * barValue) / adjustedFinalValue;
      barValues.push(inHours(barValue));
      sectionsPercentage.push(perc);
    }
  });

  sectionsPercentage.push(0);
  // console.log('sectionsPercentage:', sectionsPercentage.length, sectionsPercentage);

  const separatorValues = values.filter(
    (_, i) => i !== 0 /* && i !== values.length - 1 */
  );
  // console.log('separatorValues:', separatorValues);
  // console.log('barValues:', barValues);
  // console.log('colors:', colors);

  const iposition = ifTime2minutes(position);
  iposition?.add(finalValue.days(), 'd');
  const circleValue =
    iposition != null &&
    iposition >= ivalues[0] &&
    iposition <= finalValue &&
    adjustedFinalValue !== 0
      ? (100 * (iposition - ivalues[0])) / adjustedFinalValue
      : null;

  return (
    <View style={styles.componentContainer}>
      {!!position && <View style={{ height: 18 }} />}

      <View>
        <>
          <View
            style={[
              styles.chartContainer,
              {
                height,
                borderRadius: borderRadius || height / 2,
              },
            ]}
          >
            {sectionsPercentage.map(
              (w, i) =>
                w > 0 && (
                  <View
                    key={i}
                    style={[
                      styles.chartBar,
                      {
                        align: 'flex-start',
                        width: `${w}%`,
                        backgroundColor: colors[i],
                        height,
                      },
                    ]}
                  >
                    {w > minBarText &&
                      colors[i] &&
                      (showValueInside ||
                        colorValuesShown.includes(colors[i])) && (
                        <Text
                          children={barValues[i]}
                          style={styles.valueInsideText}
                        />
                      )}

                    {showSeparatorValue &&
                      i > 0 &&
                      i < sectionsPercentage.length - 1 &&
                      w > 10 && (
                        <View style={styles.innerValuesContainer}>
                          <View style={styles.innerValuesHalfContainer}>
                            <Text
                              children={separatorValues[i - 1]}
                              style={[
                                styles.innerValueText,
                                { alignSelf: 'flex-start' },
                              ]}
                            />
                          </View>
                          <View style={styles.innerValuesHalfContainer}>
                            <Text
                              children={separatorValues[i]}
                              style={[
                                styles.innerValueText,
                                { alignSelf: 'flex-end' },
                              ]}
                            />
                          </View>
                        </View>
                      )}
                  </View>
                )
            )}
          </View>

          {animated && <ShinyEffect time={2000} />}

          {!!circleValue && (
            <>
              <View
                style={[
                  styles.TriangleShapeCSS,
                  { borderBottomColor: positionColor.toLowerCase() },
                  {
                    position: 'absolute',
                    left: `${circleValue}%`,
                    height,
                  },
                ]}
              />
              <View
                style={[
                  styles.VertLine,
                  {
                    position: 'absolute',
                    left: `${circleValue}%`,
                    height: height + 5,
                    backgroundColor: positionColor.toLowerCase(),
                  },
                ]}
              />
            </>
          )}
        </>
      </View>
    </View>
  );
};

