import * as CustomCode from '../CustomCode';

const isCameraPermissionGranted = async Variables => {
  console.log(`testPermissions: ${Variables.testPermissions}`);
  if (Variables.testPermissions) return false;

  const isDevice =
    CustomCode.Device.isDevice && CustomCode.Platform.OS !== 'web';

  if (isDevice) {
    const { status } = await CustomCode.Camera.getCameraPermissionsAsync();
    console.log(`Camera Permission status: ${status}`);

    return status === 'granted';
  } else return true;
};

export default isCameraPermissionGranted;
