import * as Linking from 'expo-linking';
import * as Location from 'expo-location';

import { MD5 } from './MD5';

/*
    Funcioes de validación de URIs embebidos en QRs
 */

const uriFormat = uri => {
  const fmt = /.*:\/\/[^\?\/]*(.).*/.exec(uri)[1] == '/' ? 'rn' : 'classic';
  // console.log(`uriFormat: ${fmt}`);

  // return argSep = /.*:\/\/[^\?\/]*(.).*/.exec(uri)[1] == '/' ? 'rn' : '';
  return fmt;
};

/*
  fieldFormat: tiene el formato de RN Navigation, ej: 'QrpunchScreen/:ti?/:ex?/:ms?/:ci?/:cc?/:li?/:d?/:ll?/:lt?'

  La firma se calcula sobre el uri completo, ya sea en el formato RNNav (/parm1/parm2/parm3...) 
  como en el clásico (?prm1=val1&parm2=val2&parm3=val3...)

  Fields['ms'] = MD5(`${qrdata}${argSep}${rawArgs}|${signKey}`).slice(0, signLength);
*/

// Construye una lista de argumentos en formato RN o clásico a partir
// de un objeto de valores (fields) u un formato
// fieldOrder:   :ti?/:ex?/:ms?/:ci?/:cc?/:li?/:d?/:ll?/:lt?
//
export const BuildArgs = (
  fields,
  fieldOrder,
  RNUrl = true,
  incMSeg = false
) => {
  var rslt = '';

  const makeArg = (n, a) =>
    RNUrl ? `/${a ? a : '_'}` : a ? `${rslt?.length ? '&' : '?'}${n}=${a}` : '';

  const forder = fieldOrder.split('/');
  // console.log(`BuildArgs:fields: ${JSON.stringify(fields, undefined, 2)}`);
  // console.log(`BuildArgs:forder: ${forder}`);

  for (var p of forder) {
    // let pn = /:*([(a-z),(A-Z),(0-9)]*)\?*/.exec(p)[1];
    let pn = /:?([^\?]*)\??/.exec(p)[1];
    // console.log(`pn: ${pn}`);

    if (incMSeg || pn != 'ms') rslt += makeArg(pn, fields[pn]);
  }

  // console.log(`BuildArgs: ${rslt}`);
  return rslt;
};

export const GetParamValue = (aParam, uri, fields) => {
  const forder = fields.split('/').map(f => /:?(.*)\?/.exec(f)[1]); // Convierto en array y limpio los nombres
  const paramLoc = forder.indexOf(aParam);

  if (uriFormat(uri) == 'rn') {
    // console.log(`uriFormat: rn`);
    //   Separo el host y ruta de los params con /
    const uriParts = /(.*:\/\/)([^\/]*)(.*)/.exec(uri);
    const args = uriParts[3];
    const fieldValues = args.split('/').slice(1);

    return fieldValues[paramLoc];
  } else {
    // console.log(`uriFormat: classic`);
    const uriParts = /(.*:\/\/)([^\?]*)(.*)/.exec(uri);
    // console.log(`uriParts: ${uriParts}`);

    const args = uriParts[3].slice(1);
    // console.log(`args: ${args}`);

    const fieldValues = args.split('&');
    // console.log(`fieldValues: ${fieldValues}`);

    return fieldValues[paramLoc].split('=')[1];
  }
};

export const CheckUriSignature = (uri, { fields, signature }) => {
  // uri:  dss://QrpunchScreen/5/23/da017893a426020c/2/1/4/a/-58.6730442/-34.4009529

  // console.log(` CheckUriSignature (uri: ${uri}, fields: ${fields}, signature: ${signature})`);

  if (!signature) return true;

  if (!fields || !uri) return false;

  // console.log(` CheckUriSignature parms ok`);

  //  Determino que nro de parametro es el ms
  const aFOrder = fields.split('/').map(f => /:?(.*)\?/.exec(f)[1]); // Convierto en array y limpio los nombres
  // console.log(`aFOrder: ${aFOrder}`);
  const msLoc = aFOrder.indexOf('ms');
  // console.log(`msPos: ${msLoc}`);

  //   Extraigo el ms
  const msgSig = GetParamValue('ms', uri, fields);
  // console.log(`ms: '${msgSig}', pos:${msLoc}`);

  var checked = false;

  if (uriFormat(uri) == 'rn') {
    // console.log(`uriFormat: rn`);

    //   Separo el host y ruta de los params con /
    const uriParts = /(.*:\/\/)([^\/]*)(.*)/.exec(uri);
    const [host, screen, args] = [uriParts[1], uriParts[2], uriParts[3]];
    // // console.log(host, screen, args);

    const fieldValues = args.split('/').slice(1);
    // console.log(fieldValues);

    const toSign =
      `${host}${screen}/` + fieldValues.filter((f, i) => i != msLoc).join('/');
    // console.log(`toSign: ${toSign}`);

    //   Genero MD5 del resto de los params con la clave
    const msgDigest = MD5(`${toSign}|${signature}`);
    // console.log(`msgDigest: ${msgDigest}`);

    //   Comparo con el ms
    checked = msgDigest.slice(0, msgSig.length) == msgSig;
  } else {
    // Si no es RN
    // console.log(`uriFormat: clasic`);

    //  Separo el host y ruta de los params con ?
    const uriParts = /(.*:\/\/)([^\?]*)(.*)/.exec(uri);
    const [host, screen, args] = [
      uriParts[1],
      uriParts[2],
      uriParts[3].slice(1),
    ];
    // console.log(host, screen, args);

    const fieldValues = args.split('&');
    // console.log(fieldValues);

    const toSign =
      `${host}${screen}?` + fieldValues.filter((f, i) => i != msLoc).join('&');
    // console.log(`toSign: ${toSign}`);

    //  Genero MD5 del resto de los params con la clave
    const msgDigest = MD5(`${toSign}|${signature}`);
    // console.log(`msgDigest: ${msgDigest}`);

    //  Comparo con el ms
    checked = msgDigest.slice(0, msgSig.length) == msgSig;
  }

  // console.log(`CheckUriSignature: ${checked}`)
  return checked;
};

export const CalculateGeoDistance = (pos1, pos2) => {
  const toRadian = n => (n * Math.PI) / 180;

  // console.log(jlog({pos1}));
  // console.log(jlog({pos2}));
  let lat2 = pos2.latitude;
  let lon2 = pos2.longitude;
  let lat1 = pos1.latitude;
  let lon1 = pos1.longitude;

  // console.log(lat1, lon1 + "===" + lat2, lon2);

  let R = 6371000; //mts
  let x1 = lat2 - lat1;
  let dLat = toRadian(x1);
  let x2 = lon2 - lon1;
  let dLon = toRadian(x2);
  let a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRadian(lat1)) *
      Math.cos(toRadian(lat2)) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  let c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  let d = R * c;
  // console.log(`distance==${d}`);
  return d;
};

export const CheckGeolocationAsync = async (
  uri,
  { distance = 100, fields }
) => {
  // const { hostname, path, queryParams } = Linking.parse(uri);       // Linking.parse mo funciona porque el formato RN no tiene parametros http
  // console.log(`hostname: ${hostname}, path: ${path}, queryParams: ${JSON.stringify(queryParams)}`);

  // const qrPos = {latitude: -34.402227, longitude: -58.671820};    // Prueba a 177m
  // const qrPos = {latitude: -34.401532, longitude: -58.673637};    // Prueba a 81m
  // console.log(`queryParams: ${JSON.stringify(queryParams)}`);

  // const qrPos = {latitude: queryParams['lt'], longitude: queryParams['ll']};
  const qrPos = {
    latitude: GetParamValue('lt', uri, fields),
    longitude: GetParamValue('ll', uri, fields),
  };
  const myPos = await Location.getCurrentPositionAsync();

  return CalculateGeoDistance(qrPos, myPos.coords) <= distance;
};

export const CheckUriAsync = async (uri, options) => {
  // console.log(`Checking uri: ${uri}, options: ${JSON.stringify(options)} ...`);

  if (!CheckUriSignature(uri, options)) {
    console.log('Invalid signature');
    return false;
  }

  // console.log('Checking location...');
  if (!(await CheckGeolocationAsync(uri, options))) {
    console.log('Invalid location');
    return false;
  }

  return true;
};
